arguments.command:
cat > /etc/nginx/sites-available/novnc <<'EOF'
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    # Redirect root to the noVNC client, auto-connecting to the proxied websocket.
    location = / {
        return 302 /vnc.html?autoconnect=true&resize=scale&path=websockify;
    }

    # noVNC static assets + websocket proxied to websockify (serving /usr/share/novnc on 6080)
    location / {
        proxy_pass http://127.0.0.1:6080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 61s;
        proxy_buffering off;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/novnc /etc/nginx/sites-enabled/novnc
nginx -t 2>&1

